package org.apache.commons.math3.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class OpenMapRealVector_ebeDivide_TriageGen0Test {

    @Test
    public void testEbeDivideNormalCase() {
        double[] values1 = {1.0, 2.0, 0.0, 4.0};
        double[] values2 = {2.0, 1.0, 5.0, 2.0};
        OpenMapRealVector v1 = new OpenMapRealVector(values1);
        OpenMapRealVector v2 = new OpenMapRealVector(values2);

        OpenMapRealVector result = v1.ebeDivide(v2);

        assertEquals(4, result.getDimension());
        assertEquals(0.5, result.getEntry(0), 1e-10);
        assertEquals(2.0, result.getEntry(1), 1e-10);
        assertEquals(0.0, result.getEntry(2), 1e-10);
        assertEquals(2.0, result.getEntry(3), 1e-10);
    }

    @Test
    public void testEbeDivideWithZeroInDenominator() {
        double[] values1 = {1.0, 4.0};
        double[] values2 = {2.0, 0.0};
        OpenMapRealVector v1 = new OpenMapRealVector(values1);
        OpenMapRealVector v2 = new OpenMapRealVector(values2);

        OpenMapRealVector result = v1.ebeDivide(v2);

        assertEquals(0.5, result.getEntry(0), 1e-10);
        assertTrue(Double.isInfinite(result.getEntry(1)));
    }

    @Test
    public void testEbeDivideWithNaN() {
        double[] values1 = {1.0, 0.0};
        double[] values2 = {2.0, 0.0};
        OpenMapRealVector v1 = new OpenMapRealVector(values1);
        OpenMapRealVector v2 = new OpenMapRealVector(values2);

        OpenMapRealVector result = v1.ebeDivide(v2);

        assertEquals(0.5, result.getEntry(0), 1e-10);
        // 0.0 / 0.0 is NaN
        assertTrue(Double.isNaN(result.getEntry(1)));
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeDivideDimensionMismatch() {
        OpenMapRealVector v1 = new OpenMapRealVector(new double[]{1.0, 2.0});
        OpenMapRealVector v2 = new OpenMapRealVector(new double[]{1.0, 2.0, 3.0});
        v1.ebeDivide(v2);
    }

    @Test
    public void testEbeDivideSparseToDense() {
        // v1 is sparse (only index 1 is non-zero)
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(1, 10.0);

        // v2 is full
        double[] values2 = {2.0, 5.0, 10.0};
        OpenMapRealVector v2 = new OpenMapRealVector(values2);

        OpenMapRealVector result = v1.ebeDivide(v2);

        assertEquals(3, result.getDimension());
        assertEquals(0.0, result.getEntry(0), 1e-10);
        assertEquals(2.0, result.getEntry(1), 1e-10);
        assertEquals(0.0, result.getEntry(2), 1e-10);
    }

    @Test
    public void testEbeDivideEmptyVector() {
        OpenMapRealVector v1 = new OpenMapRealVector(0);
        OpenMapRealVector v2 = new OpenMapRealVector(0);

        OpenMapRealVector result = v1.ebeDivide(v2);

        assertEquals(0, result.getDimension());
    }

    @Test
    public void testEbeDivideNegativeValues() {
        OpenMapRealVector v1 = new OpenMapRealVector(new double[]{-10.0, 10.0});
        OpenMapRealVector v2 = new OpenMapRealVector(new double[]{2.0, -5.0});

        OpenMapRealVector result = v1.ebeDivide(v2);

        assertEquals(-5.0, result.getEntry(0), 1e-10);
        assertEquals(-2.0, result.getEntry(1), 1e-10);
    }
}
